29	Sha256::Sha256()
30	    : state_{0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a,
31	             0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19} {}
