33	void Sha256::process_block(const unsigned char* block) {
34	    std::uint32_t w[64];
35	    for (int i = 0; i < 16; ++i) {
36	        w[i] = (static_cast<std::uint32_t>(block[i * 4]) << 24) |
37	               (static_cast<std::uint32_t>(block[i * 4 + 1]) << 16) |
38	               (static_cast<std::uint32_t>(block[i * 4 + 2]) << 8) |
39	               (static_cast<std::uint32_t>(block[i * 4 + 3]));
40	    }
41	    for (int i = 16; i < 64; ++i) {
42	        const std::uint32_t s0 = rotr(w[i - 15], 7) ^ rotr(w[i - 15], 18) ^ (w[i - 15] >> 3);
43	        const std::uint32_t s1 = rotr(w[i - 2], 17) ^ rotr(w[i - 2], 19) ^ (w[i - 2] >> 10);
44	        w[i] = w[i - 16] + s0 + w[i - 7] + s1;
45	    }
46	
47	    std::uint32_t a = state_[0], b = state_[1], c = state_[2], d = state_[3];
48	    std::uint32_t e = state_[4], f = state_[5], g = state_[6], h = state_[7];
49	
50	    for (int i = 0; i < 64; ++i) {
51	        const std::uint32_t s1 = rotr(e, 6) ^ rotr(e, 11) ^ rotr(e, 25);
52	        const std::uint32_t ch = (e & f) ^ (~e & g);
53	        const std::uint32_t t1 = h + s1 + ch + kRoundConstants[i] + w[i];
54	        const std::uint32_t s0 = rotr(a, 2) ^ rotr(a, 13) ^ rotr(a, 22);
55	        const std::uint32_t maj = (a & b) ^ (a & c) ^ (b & c);
56	        const std::uint32_t t2 = s0 + maj;
57	        h = g;
58	        g = f;
59	        f = e;
60	        e = d + t1;
61	        d = c;
62	        c = b;
63	        b = a;
64	        a = t1 + t2;
65	    }
66	
67	    state_[0] += a;
68	    state_[1] += b;
69	    state_[2] += c;
70	    state_[3] += d;
71	    state_[4] += e;
72	    state_[5] += f;
73	    state_[6] += g;
74	    state_[7] += h;
75	}
